// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        // keep the deciding value in the admissible domain: base token must be a
        // non-zero address, otherwise both versions coincide
        vm.assume(baseToken != address(0));
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        );

        // GENERAL RULE: initialize always records the configured base token,
        // observable through the public getter c.baseToken().
        assertTrue(c.baseToken() == baseToken);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // General rule: for ANY admissible initialize arguments, after initialize succeeds
        // the stored base token equals the _baseToken argument passed in.
        // Admissible domain: feeRate must be <= 5000; choose _nft and _baseToken so the
        // distinguishing case (_baseToken != _nft) stays reachable, while still allowing
        // the (rarer) equal case for generality.
        _feeRate = uint16(bound(_feeRate, 0, 5_000));
        if (_baseToken == _nft) {
            // make addresses distinct so the rule is checked on the general case;
            // this preserves admissibility (any distinct pair is admissible)
            if (_nft == address(0)) _nft = address(uint160(1));
            else _baseToken = address(uint160(uint256(uint160(_nft)) + 1));
        }

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        assertTrue(c.baseToken() == _baseToken);
    }
}

