// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        uint256 decRaw,
        address nftAddr
    ) public {
        uint8 d = uint8(bound(decRaw, 0, 17)); // <18 so mutant's exponent 18 differs from 36-d
        vm.assume(virtualNft > 0);
        feeRate = uint16(bound(feeRate, 0, 5000)); // avoid FeeRateTooHigh in reference

        ERC20Mock baseToken = new ERC20Mock(d);

        c.initialize(
            address(baseToken),
            nftAddr,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        uint256 expected = uint256(virtualBase) * (10 ** (36 - d)) / uint256(virtualNft);
        assertTrue(c.price() == expected);
    }
}

contract ERC20Mock {
    uint8 public immutable decimals;

    constructor(uint8 _decimals) {
        decimals = _decimals;
    }
}

